import React, { useState, useEffect } from 'react';
import axios from 'axios';

const ClienteList = () => {
  const [clientes, setClientes] = useState([]);
  const [paginaAtual, setPaginaAtual] = useState(1);
  const [clientesPorPagina, setClientesPorPagina] = useState(5); // Por exemplo, 5 clientes por página

  // Função para carregar os clientes com base na página atual
  const carregarClientes = async () => {
    try {
      const response = await axios.get(`http://localhost:8080/clientes?page=${paginaAtual}&size=${clientesPorPagina}`);
      setClientes(response.data);
    } catch (error) {
      console.error('Erro ao carregar clientes:', error);
    }
  };

  useEffect(() => {
    carregarClientes();
  }, [paginaAtual]);

  const mudarPagina = (pagina) => {
    if (pagina >= 1) {
      setPaginaAtual(pagina);
    }
  };

  return (
    <div>
      <h2>Lista de Clientes</h2>

      {/* Exibir os clientes */}
      <div className="clientes-list">
        {clientes.map(cliente => (
          <div key={cliente.id} className="cliente-card">
            <h3>{cliente.nome}</h3>
            <p>{cliente.email}</p>
            <p>{cliente.telefone}</p>
          </div>
        ))}
      </div>

      {/* Paginação */}
      <div className="pagination">
        <button onClick={() => mudarPagina(paginaAtual - 1)} disabled={paginaAtual === 1}>
          Anterior
        </button>
        <span>Página {paginaAtual}</span>
        <button onClick={() => mudarPagina(paginaAtual + 1)}>
          Próxima
        </button>
      </div>
    </div>
  );
};

export default ClienteList;
